/**
 * 全局账号态。主题控制、设置面板和抽屉同步共用同一份会话，避免各自
 * 调用 Hook 后得到互不相干的登录状态。
 */
import { create } from "zustand";
import type { AuthUser, ThemeId } from "@inkflow/shared";
import {
  ApiError,
  fetchAccount,
  loginWithPassword,
  loginDeveloper,
  registerWithPassword,
  requestPhoneBindCode,
  requestSmsCode,
  signOutRemote,
  updateRemoteTheme,
  verifyPhoneBindCode,
  verifySmsCode,
} from "./accountApi";

const SESSION_STORAGE_KEY = "inkflow:account:v1";

export interface StoredSession {
  accessToken: string;
  refreshToken: string;
  expiresAt: string;
  user: AuthUser;
}

export type AccountStatus = "anonymous" | "signed-in";

function normalizeSession(value: unknown): StoredSession | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<StoredSession>;
  if (
    typeof candidate.accessToken !== "string" ||
    !candidate.accessToken ||
    !candidate.user ||
    typeof candidate.user.id !== "string"
  ) {
    return null;
  }
  return {
    accessToken: candidate.accessToken,
    refreshToken:
      typeof candidate.refreshToken === "string" ? candidate.refreshToken : "",
    expiresAt:
      typeof candidate.expiresAt === "string" ? candidate.expiresAt : "",
    user: candidate.user,
  };
}

export function loadStoredSession(): StoredSession | null {
  if (typeof localStorage === "undefined") return null;
  try {
    return normalizeSession(
      JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY) ?? "null"),
    );
  } catch {
    return null;
  }
}

function persistSession(session: StoredSession | null) {
  if (typeof localStorage === "undefined") return;
  try {
    if (session) {
      localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
    } else {
      localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  } catch {
    // 隐私模式：登录仍有效，只是刷新后需要重新登录。
  }
}

function describeError(error: unknown) {
  if (error instanceof ApiError) {
    if (error.code === "invalid_credentials") return "邮箱或密码不正确。";
    if (error.code === "email_registered") return "这个邮箱已经注册过了。";
    if (error.code === "phone_registered") {
      return "这个手机号已经绑定了另一个账号。";
    }
    if (error.code === "sms_not_configured") {
      return "短信通道尚未配置，请使用密码登录或稍后再试。";
    }
    if (error.code === "sms_send_failed") {
      return "验证码发送失败，请稍后重试。";
    }
    if (error.code === "code_expired") return "验证码已过期，请重新获取。";
    if (error.code === "invalid_code") return "验证码不正确，请检查后重试。";
    if (error.status === 401) return "登录已过期，请重新登录。";
    if (error.status === 400) return "请检查填写内容后重试。";
    return error.message;
  }
  return "连接不到服务器，便条先存在本机，联网后再登录即可同步。";
}

interface AccountState {
  session: StoredSession | null;
  bootstrapped: boolean;
  busy: boolean;
  error: string | null;
  devCode: string | null;
  bootstrap: () => Promise<void>;
  signInWithDeveloper: () => Promise<boolean>;
  registerWithPassword: (input: {
    displayName: string;
    email: string;
    password: string;
  }) => Promise<boolean>;
  signInWithPassword: (input: {
    email: string;
    password: string;
  }) => Promise<boolean>;
  sendCode: (phone: string) => Promise<boolean>;
  signInWithCode: (phone: string, code: string) => Promise<boolean>;
  requestPhoneBind: (phone: string) => Promise<boolean>;
  verifyPhoneBind: (phone: string, code: string) => Promise<boolean>;
  signOut: () => Promise<void>;
  clearError: () => void;
  setUserTheme: (themeId: ThemeId) => void;
}

export const useAccountStore = create<AccountState>((set, get) => ({
  session: loadStoredSession(),
  bootstrapped: false,
  busy: false,
  error: null,
  devCode: null,

  async bootstrap() {
    if (get().bootstrapped) return;
    const token = loadStoredSession()?.accessToken;
    if (!token) {
      set({ bootstrapped: true });
      return;
    }
    try {
      const payload = await fetchAccount(token);
      set((state) => {
        if (!state.session || state.session.accessToken !== token) {
          return { bootstrapped: true };
        }
        const session = { ...state.session, user: payload.user };
        persistSession(session);
        return { session, bootstrapped: true };
      });
    } catch (caught) {
      if (caught instanceof ApiError && caught.status === 401) {
        persistSession(null);
        set({
          session: null,
          bootstrapped: true,
          error: "登录已过期，请重新登录。",
        });
        return;
      }
      set({ bootstrapped: true });
    }
  },

  async signInWithDeveloper() {
    set({ busy: true, error: null });
    try {
      const payload = await loginDeveloper();
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async registerWithPassword(input) {
    set({ busy: true, error: null });
    try {
      const payload = await registerWithPassword(input);
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async signInWithPassword(input) {
    set({ busy: true, error: null });
    try {
      const payload = await loginWithPassword(input);
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async sendCode(phone) {
    set({ busy: true, error: null });
    try {
      const result = await requestSmsCode(phone);
      set({ devCode: result.devCode ?? null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async signInWithCode(phone, code) {
    set({ busy: true, error: null });
    try {
      const payload = await verifySmsCode(phone, code);
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async requestPhoneBind(phone) {
    const token = get().session?.accessToken;
    if (!token) {
      set({ error: "请先登录，再绑定手机号。" });
      return false;
    }
    set({ busy: true, error: null });
    try {
      const result = await requestPhoneBindCode(token, phone);
      set({ devCode: result.devCode ?? null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async verifyPhoneBind(phone, code) {
    const token = get().session?.accessToken;
    if (!token) {
      set({ error: "请先登录，再绑定手机号。" });
      return false;
    }
    set({ busy: true, error: null });
    try {
      const payload = await verifyPhoneBindCode(token, phone, code);
      set((state) => {
        if (!state.session) return { error: null, devCode: null };
        const session = { ...state.session, user: payload.user };
        persistSession(session);
        return { session, error: null, devCode: null };
      });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async signOut() {
    const token = get().session?.accessToken;
    persistSession(null);
    set({ session: null, error: null, devCode: null });
    if (!token) return;
    try {
      await signOutRemote(token);
    } catch {
      // 本机会话已经清掉即可，服务器失败不阻塞退出。
    }
  },

  clearError() {
    set({ error: null, devCode: null });
  },

  setUserTheme(themeId) {
    set((state) => {
      if (!state.session) return state;
      const session = {
        ...state.session,
        user: { ...state.session.user, themeId },
      };
      persistSession(session);
      return { session };
    });
  },
}));

export async function syncThemePreference(token: string, themeId: ThemeId) {
  return updateRemoteTheme(token, themeId);
}

export type InkflowAccount = AccountState & {
  user: AuthUser | null;
  accessToken: string | null;
  status: AccountStatus;
};

export function useInkflowAccount(): InkflowAccount {
  const state = useAccountStore();
  return {
    ...state,
    user: state.session?.user ?? null,
    accessToken: state.session?.accessToken ?? null,
    status: state.session ? "signed-in" : "anonymous",
  };
}
