import {
  Navigate,
  Route,
  Routes,
  useLocation,
  useNavigate,
  useParams,
} from "react-router-dom";
import { Archive, ChevronRight, CloudOff, X } from "lucide-react";
import { lazy, Suspense, useEffect, type ReactNode } from "react";
import { BookReaderPage } from "./components/book/BookReaderPage";
import { KnowledgeBookPage } from "./components/knowledge/KnowledgeBookPage";
import { knowledgeBookById } from "./components/knowledge/knowledgeCatalog";
import { LiquidGlass } from "./components/reactbits/LiquidGlass";
import { HomeLobby } from "./components/home/HomeLobby";
import { LandingPage } from "./components/landing/LandingPage";
import { NotFoundPage } from "./components/not-found/NotFoundPage";
import { PersistentDock } from "./components/navigation/PersistentDock";
import { SiteIntro } from "./components/intro/SiteIntro";
import { useAccountStore } from "./lib/auth";
import { cn } from "./lib/cn";
import { useInkFlow } from "./store/inkflow";
import { ThemeController } from "./theme/ThemeController";

const KnowledgeLibraryPage = lazy(() =>
  import("./components/knowledge/KnowledgeLibraryPage").then((module) => ({
    default: module.KnowledgeLibraryPage,
  })),
);
const PracticeLibraryPage = lazy(() =>
  import("./components/practice/PracticeLibraryPage").then((module) => ({
    default: module.PracticeLibraryPage,
  })),
);
const PracticeDrillPage = lazy(() =>
  import("./components/practice/PracticeDrillPage").then((module) => ({
    default: module.PracticeDrillPage,
  })),
);
const CorpusPage = lazy(() =>
  import("./components/corpus/CorpusPage").then((module) => ({
    default: module.CorpusPage,
  })),
);
const VocabularyPage = lazy(() =>
  import("./components/vocabulary/VocabularyPage").then((module) => ({
    default: module.VocabularyPage,
  })),
);
const ComponentLabPage = lazy(() =>
  import("./components/reactbits/ComponentLabPage").then((module) => ({
    default: module.ComponentLabPage,
  })),
);

function ArchiveDrawer() {
  const navigate = useNavigate();
  const { archiveOpen, setArchiveOpen } = useInkFlow();
  if (!archiveOpen) return null;

  return (
    <div
      className="drawer-backdrop"
      role="presentation"
      onClick={() => setArchiveOpen(false)}
    >
      <LiquidGlass
        as="aside"
        className="archive-drawer"
        role="dialog"
        aria-modal="true"
        aria-label="Archive"
        intensity="strong"
        onClick={(event) => event.stopPropagation()}
      >
        <header>
          <div>
            <span className="eyebrow">Stored beneath the desk</span>
            <h2>Archive</h2>
          </div>
          <button
            type="button"
            className="icon-button"
            onClick={() => setArchiveOpen(false)}
            aria-label="Close archive"
          >
            <X size={18} />
          </button>
        </header>
        <div className="archive-list">
          {[
            ["Last summer’s reading list", "18 notes · archived 2 weeks ago"],
            ["Interview vocabulary, first draft", "42 phrases · archived last month"],
            ["Teaching observation notes", "9 pages · archived in June"],
          ].map(([title, meta]) => (
            <button
              type="button"
              key={title}
              onClick={() => {
                setArchiveOpen(false);
                navigate("/library");
              }}
            >
              <Archive size={18} />
              <span>
                <strong>{title}</strong>
                <small>{meta}</small>
              </span>
              <ChevronRight size={16} />
            </button>
          ))}
        </div>
      </LiquidGlass>
    </div>
  );
}

function OfflineBanner() {
  const { apiOnline, deepseekConfigured, bootstrapped } = useInkFlow();
  const { pathname } = useLocation();
  // The landing is a closed composition — its nav sits dead centre and the
  // banner would land right on top of it. The notice belongs to the room,
  // where the reader is actually working against the API.
  if (pathname === "/welcome") return null;
  if (!bootstrapped || apiOnline) return null;
  return (
    <div className="offline-banner">
      <CloudOff size={15} />
      <span>
        Local mode is active. The interface and sample corpus remain available;
        configure the API to enable DeepSeek and persistent sync.
      </span>
      <small>{deepseekConfigured ? "API unavailable" : "No API key"}</small>
    </div>
  );
}

function Toast() {
  const { toast } = useInkFlow();
  return (
    <div className={cn("toast", toast && "is-visible")} role="status">
      {toast?.message}
    </div>
  );
}

/** 懒加载页面下载的那几百毫秒以前是一片空白，现在用整页幕布盖住（styles.css 的 .route-curtain）。 */
function LazyRoute({ children }: { children: ReactNode }) {
  return (
    <Suspense fallback={<div className="route-curtain" aria-hidden="true" />}>
      {children}
    </Suspense>
  );
}

function BookRoute() {
  const { bookId } = useParams();
  if (knowledgeBookById(bookId)) return <KnowledgeBookPage />;
  return <BookReaderPage />;
}

export function App() {
  const bootstrap = useInkFlow((state) => state.bootstrap);
  const bootstrapAccount = useAccountStore((state) => state.bootstrap);

  useEffect(() => {
    void bootstrap();
    void bootstrapAccount();
  }, [bootstrap, bootstrapAccount]);

  return (
    <div className="inkflow-app">
      <ThemeController />
      <SiteIntro />
      <OfflineBanner />
      <div className="motion-route-stage" data-motion-root>
        <Routes>
          {/* 打开 Leafia 就是走进书房：首页空间即书架本体。原来的动效落地页
              挪到 /welcome —— 它还在，只是不再是正门。 */}
          <Route path="/" element={<HomeLobby />} />
          <Route path="/welcome" element={<LandingPage />} />
          <Route path="/shelf" element={<HomeLobby />} />
          <Route path="/study" element={<Navigate to="/shelf" replace />} />
          <Route
            path="/inkverse/:bookId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/library"
            element={<KnowledgeLibraryPage />}
          />
          <Route
            path="/library/:categoryId"
            element={<KnowledgeLibraryPage />}
          />
          <Route
            path="/write/:noteId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/write/:noteId/:pageId"
            element={<Navigate to="/library" replace />}
          />
          <Route path="/book/:bookId" element={<BookRoute />} />
          <Route
            path="/corpus"
            element={
              <LazyRoute>
                <CorpusPage />
              </LazyRoute>
            }
          />
          <Route path="/reading" element={<Navigate to="/library" replace />} />
          <Route
            path="/reading/:chapterId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/practice"
            element={
              <LazyRoute>
                <PracticeLibraryPage />
              </LazyRoute>
            }
          />
          <Route
            path="/drill/:trackId"
            element={
              <LazyRoute>
                <PracticeDrillPage />
              </LazyRoute>
            }
          />
          <Route
            path="/vocabulary"
            element={
              <LazyRoute>
                <VocabularyPage />
              </LazyRoute>
            }
          />
          <Route
            path="/components"
            element={
              <LazyRoute>
                <ComponentLabPage />
              </LazyRoute>
            }
          />
          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </div>
      <PersistentDock />
      <ArchiveDrawer />
      <Toast />
    </div>
  );
}
