import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
} from "react";
import "./infinite-gallery.css";

/**
 * Infinite Gallery —— 无边的 3D 卡片场。
 *
 * 借自 React Bits Pro 的同名组件（endless field of images you drift through
 * in 3D）的形态：一叠卡片铺在一条向前的隧道里，视线慢慢往前漂，卡片从
 * 远处淡入、掠过身边、在近处淡出，再回到最远处，永远没有尽头。
 *
 * 这里不摆图片文件，摆的是「背过的卡片」：每张卡就是一枚单词卡（词 +
 * 释义 + 复习轮次），卡面用主题色画出来，所以换皮肤时整片卡场跟着走。
 *
 * 三种输入：
 *   - 指针（不按）→ 视线偏移，像偏头看
 *   - 拖动       → 转动卡场
 *   - 滚轮       → 加速漂移，松手后自己缓回怠速
 *
 * prefers-reduced-motion 或者窄屏时退成静态网格：同样的卡片，一屏能看全，
 * 不漂也不转。
 */

export interface InfiniteGalleryItem {
  id: string;
  /** 卡面上的主词（背过的那个词）。 */
  word: string;
  /** 词性/分类这类一两个字的标记。 */
  tag?: string;
  /** 释义或用例，一行到两行。 */
  meaning?: string;
  /** 已复习轮次；卡面右下角的小字。 */
  rounds?: number;
}

interface InfiniteGalleryProps {
  items: InfiniteGalleryItem[];
  onSelect?: (item: InfiniteGalleryItem) => void;
  /** 漂移速度（px/秒），默认很慢 —— 这是一片场，不是跑马灯。 */
  drift?: number;
  className?: string;
  emptyLabel?: string;
  /**
   * 强制静态网格（不漂、不转、不响应滚轮）。
   * 词汇积累要的是一页安静的卡片，所以书房里直接传 true；
   * 窄屏和 prefers-reduced-motion 本来也会退到同一套网格。
   */
  still?: boolean;
}

/** 隧道的总深度：一张卡从最远处走到眼前要穿过的像素数。 */
const TUNNEL = 2400;
/** 卡片场横向/纵向铺开的半径，随容器尺寸缩放。 */
const FIELD_X = 0.62;
const FIELD_Y = 0.44;

/** 由字符串算一个稳定的 0..1 伪随机数：同一张卡每次都在同一个位置。 */
function hash01(input: string, salt: number) {
  let hash = 2166136261 ^ salt;
  for (let index = 0; index < input.length; index += 1) {
    hash = Math.imul(hash ^ input.charCodeAt(index), 16777619);
  }
  hash ^= hash >>> 15;
  return ((hash >>> 0) % 100000) / 100000;
}

function staticLayout(items: InfiniteGalleryItem[]) {
  return items.map((item, index) => ({
    item,
    x: (hash01(item.id, 1) * 2 - 1) * FIELD_X,
    y: (hash01(item.id, 2) * 2 - 1) * FIELD_Y,
    z: (index / Math.max(1, items.length)) * TUNNEL,
    tilt: (hash01(item.id, 3) * 2 - 1) * 6,
  }));
}

export function InfiniteGallery({
  items,
  onSelect,
  drift = 46,
  className = "",
  emptyLabel = "还没有背过的卡片。去单词本练一轮，卡片会出现在这里。",
  still: stillForced = false,
}: InfiniteGalleryProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const [stillScreen, setStillScreen] = useState(false);
  const still = stillForced || stillScreen;

  // 漂移、转向、速度都活在 ref 里：每帧直接改 transform，不经过 React 渲染。
  const depthRef = useRef(0);
  const speedRef = useRef(drift);
  const yawRef = useRef(0);
  const yawTargetRef = useRef(0);
  const pitchRef = useRef(0);
  const pitchTargetRef = useRef(0);
  const pointerRef = useRef({ x: 0, y: 0, down: false, lastX: 0 });
  const reducedRef = useRef(false);

  const layout = useMemo(() => staticLayout(items), [items]);

  const onPointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const x = (event.clientX - rect.left) / Math.max(1, rect.width);
    const y = (event.clientY - rect.top) / Math.max(1, rect.height);
    pointerRef.current.x = (x * 2 - 1) * 11;
    pointerRef.current.y = (y * 2 - 1) * 7;
    if (pointerRef.current.down) {
      yawTargetRef.current += (event.clientX - pointerRef.current.lastX) * 0.22;
      pointerRef.current.lastX = event.clientX;
    }
  }, []);

  const onPointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    pointerRef.current.down = true;
    pointerRef.current.lastX = event.clientX;
    event.currentTarget.setPointerCapture(event.pointerId);
  }, []);

  const onPointerUp = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    pointerRef.current.down = false;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  }, []);

  const onPointerLeave = useCallback(() => {
    pointerRef.current.x = 0;
    pointerRef.current.y = 0;
    pointerRef.current.down = false;
    yawTargetRef.current = 0;
    pitchTargetRef.current = 0;
  }, []);

  const onWheel = useCallback((event: React.WheelEvent<HTMLDivElement>) => {
    // 往前滚就往前漂：速度叠上去，之后自己缓回怠速。
    speedRef.current += event.deltaY * 1.6;
  }, []);

  // 窄屏和「减少动态效果」都退成静态网格。
  useEffect(() => {
    const query = window.matchMedia(
      "(prefers-reduced-motion: reduce), (max-width: 760px)",
    );
    const apply = () => setStillScreen(query.matches);
    apply();
    query.addEventListener("change", apply);
    return () => query.removeEventListener("change", apply);
  }, []);

  useEffect(() => {
    if (still) return;
    const viewport = viewportRef.current;
    const stage = stageRef.current;
    if (!viewport || !stage) return;
    const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = motionQuery.matches;
    let raf = 0;
    let last = performance.now();

    const loop = (now: number) => {
      raf = window.requestAnimationFrame(loop);
      const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000));
      last = now;
      const rect = viewport.getBoundingClientRect();
      const halfW = Math.max(1, rect.width / 2);
      const halfH = Math.max(1, rect.height / 2);

      // 怠速 + 惯性：滚轮叠出来的速度每秒衰减到十分之一。
      speedRef.current =
        drift + (speedRef.current - drift) * Math.exp(-1.6 * dt);
      const clampedSpeed = Math.max(-260, Math.min(520, speedRef.current));
      depthRef.current += clampedSpeed * dt;

      yawRef.current += (yawTargetRef.current - yawRef.current) * Math.min(1, dt * 4);
      pitchRef.current +=
        (pitchTargetRef.current - pitchRef.current) * Math.min(1, dt * 4);
      if (!pointerRef.current.down) {
        yawTargetRef.current *= Math.exp(-0.8 * dt);
      }
      const yaw = yawRef.current + pointerRef.current.x;
      const pitch = pitchRef.current + pointerRef.current.y;
      stage.style.transform = `rotateX(${(-pitch).toFixed(2)}deg) rotateY(${yaw.toFixed(2)}deg)`;

      for (let index = 0; index < layout.length; index += 1) {
        const node = cardRefs.current[index];
        const entry = layout[index];
        if (!node || !entry) continue;
        // t: 这张卡离镜头还有多远。0 = 最远，TUNNEL = 掠过镜头。
        let t = (entry.z - depthRef.current) % TUNNEL;
        if (t < 0) t += TUNNEL;
        const z = t - TUNNEL;
        const scale = 1 + (t / TUNNEL) * 1.35;
        const x = entry.x * halfW * (0.72 + t / TUNNEL);
        const y = entry.y * halfH * (0.72 + t / TUNNEL) + Math.sin((t / TUNNEL) * 3.1) * 10;
        // 两端都淡：远处淡入，掠到镜头前淡出，回环时看不出接缝。
        const fadeIn = Math.min(1, t / (TUNNEL * 0.16));
        const fadeOut = Math.min(1, (TUNNEL - t) / (TUNNEL * 0.12));
        const opacity = Math.max(0, Math.min(1, fadeIn * fadeOut));
        node.style.transform = `translate3d(${x.toFixed(1)}px, ${y.toFixed(1)}px, ${z.toFixed(0)}px) rotateZ(${entry.tilt}deg)`;
        node.style.opacity = opacity.toFixed(3);
        node.style.visibility = opacity <= 0.01 ? "hidden" : "visible";
        node.style.zIndex = String(1000 - Math.round(t));
        node.style.pointerEvents = opacity > 0.55 ? "auto" : "none";
      }
    };

    raf = window.requestAnimationFrame(loop);
    return () => window.cancelAnimationFrame(raf);
  }, [drift, layout, still]);

  const renderCard = (
    entry: ReturnType<typeof staticLayout>[number],
    index: number,
    style?: CSSProperties,
    extraClassName = "",
  ) => {
    const { item } = entry;
    const hue = Math.round(hash01(item.id, 7) * 360);
    return (
      <button
        key={item.id}
        type="button"
        ref={(node) => {
          cardRefs.current[index] = node;
        }}
        className={`infinite-gallery__card ${extraClassName}`.trim()}
        style={{ ...style, ["--card-hue" as string]: String(hue) }}
        onClick={() => onSelect?.(item)}
        aria-label={`词汇卡片 ${item.word}${item.meaning ? `，${item.meaning}` : ""}`}
      >
        <span className="infinite-gallery__wash" aria-hidden="true" />
        <span className="infinite-gallery__glyph" aria-hidden="true">
          {item.word.slice(0, 1).toUpperCase()}
        </span>
        <span className="infinite-gallery__word">{item.word}</span>
        {item.tag ? <span className="infinite-gallery__tag">{item.tag}</span> : null}
        {item.meaning ? (
          <span className="infinite-gallery__meaning">{item.meaning}</span>
        ) : null}
        {typeof item.rounds === "number" ? (
          <span className="infinite-gallery__rounds">
            {item.rounds > 0 ? `复习 ${item.rounds} 轮` : "待复习"}
          </span>
        ) : null}
      </button>
    );
  };

  if (!items.length) {
    return (
      <div className={`infinite-gallery infinite-gallery--empty ${className}`.trim()}>
        <p>{emptyLabel}</p>
      </div>
    );
  }

  if (still) {
    return (
      <div
        className={`infinite-gallery infinite-gallery--still ${className}`.trim()}
        role="list"
        aria-label="背过的卡片"
      >
        {layout.map((entry, index) => renderCard(entry, index, undefined, ""))}
      </div>
    );
  }

  return (
    <div
      ref={viewportRef}
      className={`infinite-gallery ${className}`.trim()}
      onPointerMove={onPointerMove}
      onPointerDown={onPointerDown}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onPointerLeave={onPointerLeave}
      onWheel={onWheel}
      role="list"
      aria-label="背过的卡片"
    >
      <div className="infinite-gallery__glow" aria-hidden="true" />
      <div ref={stageRef} className="infinite-gallery__stage">
        {layout.map((entry, index) => renderCard(entry, index))}
      </div>
      <p className="infinite-gallery__hint" aria-hidden="true">
        拖动转向 · 滚动加速
      </p>
    </div>
  );
}

export default InfiniteGallery;
