type Rgb = [number, number, number];

function parseHex(hex: string): Rgb {
  const value = hex.replace("#", "");
  const normalized =
    value.length === 3
      ? value
          .split("")
          .map((part) => `${part}${part}`)
          .join("")
      : value;
  return [
    Number.parseInt(normalized.slice(0, 2), 16),
    Number.parseInt(normalized.slice(2, 4), 16),
    Number.parseInt(normalized.slice(4, 6), 16),
  ];
}

function toHex(rgb: Rgb) {
  return `#${rgb
    .map((channel) =>
      Math.round(Math.max(0, Math.min(255, channel)))
        .toString(16)
        .padStart(2, "0"),
    )
    .join("")}`;
}

export function mixThemeColor(left: string, right: string, amount: number) {
  const [lr, lg, lb] = parseHex(left);
  const [rr, rg, rb] = parseHex(right);
  return toHex([
    lr + (rr - lr) * amount,
    lg + (rg - lg) * amount,
    lb + (rb - lb) * amount,
  ]);
}

function alphaThemeColor(hex: string, alpha: number) {
  const [red, green, blue] = parseHex(hex);
  return `rgba(${red}, ${green}, ${blue}, ${alpha})`;
}

function readableInk(background: string) {
  const [red, green, blue] = parseHex(background);
  const luminance = (red * 299 + green * 587 + blue * 114) / 1000;
  return luminance > 158 ? "#25262b" : "#fffaf3";
}

function lightTokens(
  page: string,
  accent: string,
  textSeed: string,
): ThemeTokens {
  const surface = mixThemeColor(page, "#ffffff", 0.42);
  const surfaceStrong = mixThemeColor(page, "#ffffff", 0.78);
  const ink = mixThemeColor(textSeed, "#1f2326", 0.7);
  const inkSoft = mixThemeColor(ink, "#ffffff", 0.22);
  const muted = mixThemeColor(ink, "#ffffff", 0.46);
  const faint = mixThemeColor(ink, "#ffffff", 0.64);
  const line = alphaThemeColor(ink, 0.14);
  const lineStrong = alphaThemeColor(ink, 0.25);
  const accentDeep = mixThemeColor(accent, "#000000", 0.28);
  const accentSoft = mixThemeColor(accent, "#ffffff", 0.78);
  const accentGhost = mixThemeColor(accent, "#ffffff", 0.91);
  const warmDeep = mixThemeColor(page, "#000000", 0.28);
  const warmSoft = mixThemeColor(page, "#ffffff", 0.7);

  return {
    pageStart: mixThemeColor(page, "#ffffff", 0.16),
    pageMid: mixThemeColor(page, accent, 0.15),
    pageEnd: mixThemeColor(accent, "#ffffff", 0.72),
    surface,
    surfaceStrong,
    surfaceSoft: alphaThemeColor(surfaceStrong, 0.78),
    panel: alphaThemeColor(surfaceStrong, 0.94),
    panelSoft: alphaThemeColor(surfaceStrong, 0.72),
    panelLine: alphaThemeColor(ink, 0.16),
    ink,
    inkSoft,
    muted,
    faint,
    line,
    lineStrong,
    accent,
    accentDeep,
    accentSoft,
    accentGhost,
    onAccent: readableInk(accentDeep),
    warm: page,
    warmDeep,
    warmSoft,
    onWarm: readableInk(warmDeep),
    focus: accentDeep,
    shadow: alphaThemeColor(ink, 0.15),
    scrim: alphaThemeColor(ink, 0.54),
  };
}

