interface LightThemeInput {
  id: ThemeId;
  nameZh: string;
  nameEn: string;
  description: string;
  page: string;
  accent: string;
  textSeed?: string;
}

function lightTheme(input: LightThemeInput): ThemePreset {
  const tokens = lightTokens(
    input.page,
    input.accent,
    input.textSeed ?? input.accent,
  );
  return {
    id: input.id,
    nameZh: input.nameZh,
    nameEn: input.nameEn,
    description: input.description,
    appearance: "light",
    swatch: [input.page, input.accent, tokens.surfaceStrong],
    tokens,
  };
}

