export const LEGACY_SKIN_STORAGE_KEY = "inkflow:home-skin:v1";

export function isThemeId(value: unknown): value is ThemeId {
  return typeof value === "string" && THEME_IDS.includes(value as ThemeId);
}

export function resolveStoredThemeId(value: unknown): ThemeId {
  if (isThemeId(value)) return value;
  if (
    value === "oak" ||
    value === "mist" ||
    value === "rice-charcoal" ||
    value === "ink-rouge"
  ) {
    return "moon";
  }
  return "moon";
}

export function themeCssVariables(theme: ThemePreset) {
  return {
    "--theme-page-start": theme.tokens.pageStart,
    "--theme-page-mid": theme.tokens.pageMid,
    "--theme-page-end": theme.tokens.pageEnd,
    "--theme-surface": theme.tokens.surface,
    "--theme-surface-strong": theme.tokens.surfaceStrong,
    "--theme-surface-soft": theme.tokens.surfaceSoft,
    "--theme-panel": theme.tokens.panel,
    "--theme-panel-soft": theme.tokens.panelSoft,
    "--theme-panel-line": theme.tokens.panelLine,
    "--theme-ink": theme.tokens.ink,
    "--theme-ink-soft": theme.tokens.inkSoft,
    "--theme-muted": theme.tokens.muted,
    "--theme-faint": theme.tokens.faint,
    "--theme-line": theme.tokens.line,
    "--theme-line-strong": theme.tokens.lineStrong,
    "--theme-accent": theme.tokens.accent,
    "--theme-accent-deep": theme.tokens.accentDeep,
    "--theme-accent-soft": theme.tokens.accentSoft,
    "--theme-accent-ghost": theme.tokens.accentGhost,
    "--theme-on-accent": theme.tokens.onAccent,
    "--theme-warm": theme.tokens.warm,
    "--theme-warm-deep": theme.tokens.warmDeep,
    "--theme-warm-soft": theme.tokens.warmSoft,
    "--theme-on-warm": theme.tokens.onWarm,
    "--theme-focus": theme.tokens.focus,
    "--theme-shadow": theme.tokens.shadow,
    "--theme-scrim": theme.tokens.scrim,
  } as Record<`--theme-${string}`, string>;
}
