import { gsap } from "gsap";
import { useEffect, useRef, useState } from "react";
import { useLocation } from "react-router-dom";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import { isRoomRoute } from "../../motion/motionConfig";
import { whenSceneReady } from "../../lib/scene-ready";
import "./site-intro.css";

const SESSION_KEY = "inkflow.intro.seen";

// How long the curtain holds for a cold 3D scene before letting go anyway.
// Past this the shelf's own loading plate carries the wait, so the page is
// never blank even when the scene never arrives.
const SCENE_GRACE_MS = 12_000;

const WORDMARK = "LEAFIA";
const NOTES = ["♪", "♩", "♫", "♬", "♩"];

export function SiteIntro() {
  const prefersReducedMotion = usePrefersReducedMotion();
  const location = useLocation();
  const rootRef = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  // The curtain is no longer the site's opening frame — the landing is. It
  // now belongs to the moment the reader walks into the 3D room from /shelf,
  // covering the seconds the scene needs to compile its first frame.
  const onRoomRoute = isRoomRoute(location.pathname);

  useEffect(() => {
    if (!onRoomRoute) {
      setVisible(false);
      return;
    }
    if (sessionStorage.getItem(SESSION_KEY) === "1") return;
    setVisible(true);
  }, [onRoomRoute]);

  useEffect(() => {
    if (!visible) return undefined;
    sessionStorage.setItem(SESSION_KEY, "1");
    if (prefersReducedMotion) {
      setVisible(false);
      return undefined;
    }
    const root = rootRef.current;
    if (!root) return undefined;

    const notes = root.querySelectorAll(".site-intro__note");
    const staffLines = root.querySelectorAll(".site-intro__staff-line");
    const letters = root.querySelectorAll(".site-intro__letter-glyph");
    const wash = root.querySelector(".site-intro__wash");

    // The stylesheet parks each glyph below its mask with a percentage
    // translate so the wordmark is already hidden on the first paint. GSAP
    // reads that as its own px `y`, which the entrance never touches (it
    // drives `yPercent`, a separate channel), leaving the letters clipped for
    // good once they rise. Fold the stylesheet's value onto the channel the
    // timeline animates; the frame rendered is identical.
    gsap.set(letters, { y: 0, yPercent: 118, rotate: 2.5 });

    // Two acts. The entrance always plays immediately; the exit is held back
    // until the 3D room behind the curtain has painted its first frame, so the
    // curtain never lifts onto an empty room. Between the acts the copy keeps
    // a quiet waiting rhythm (breathing staff, floating notes, pulse dots) so
    // the hold reads as "the room is being prepared", not as a stall.
    const enter = gsap.timeline({
      defaults: { ease: "power3.out" },
      paused: true,
    });
    enter
      .fromTo(
        wash,
        { clipPath: "ellipse(0% 0% at 86% 50%)" },
        {
          clipPath: "ellipse(120% 130% at 86% 50%)",
          duration: 0.84,
          ease: "power4.out",
        },
      )
      .fromTo(
        staffLines,
        {
          scaleX: 0,
          // Alternate the origin per line so the five rules weave instead of
          // repeating one sweep — the staff reads as written, not stamped.
          transformOrigin: (index: number) =>
            index % 2 === 0 ? "left center" : "right center",
        },
        { scaleX: 1, duration: 0.56, stagger: 0.05 },
        "-=0.5",
      )
      .fromTo(
        notes,
        {
          opacity: 0,
          x: 150,
          y: (index: number) => 42 + index * 18,
          rotate: (index: number) => -12 + index * 7,
          scale: 0.42,
        },
        {
          opacity: 1,
          x: 0,
          y: 0,
          rotate: (index: number) => -7 + index * 4,
          scale: 1,
          duration: 0.66,
          stagger: 0.082,
          ease: "back.out(1.5)",
        },
        "-=0.4",
      )
      .fromTo(
        letters,
        { yPercent: 118, rotate: 2.5 },
        { yPercent: 0, rotate: 0, duration: 0.62, stagger: 0.038 },
        "-=0.62",
      )
      .fromTo(
        root.querySelector(".site-intro__rule"),
        { scaleX: 0 },
        { scaleX: 1, duration: 0.5, ease: "power2.out" },
        "-=0.34",
      )
      .fromTo(
        root.querySelector(".site-intro__tagline"),
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 0.46 },
        "-=0.38",
      )
      .fromTo(
        root.querySelector(".site-intro__eyebrow"),
        { opacity: 0, x: -14 },
        { opacity: 1, x: 0, duration: 0.36 },
        "-=0.4",
      );

    const exit = gsap.timeline({
      paused: true,
      onComplete: () => setVisible(false),
    });
    exit
      .to(notes, {
        y: -36,
        rotate: (index: number) => -4 + index * 6,
        duration: 0.48,
        stagger: 0.035,
      })
      .to(
        root.querySelector(".site-intro__copy"),
        { y: -34, opacity: 0, duration: 0.46 },
        "-=0.24",
      )
      .to(
        wash,
        {
          clipPath: "ellipse(0% 0% at 86% 8%)",
          duration: 0.62,
          ease: "power3.inOut",
        },
        "-=0.28",
      )
      .to(root, { autoAlpha: 0, duration: 0.24 }, "-=0.12");

    // The curtain only ever plays on the room route, where the 3D scene is
    // always mounting behind it — so there is always something to wait for.
    let enterDone = false;
    let readySeen = false;
    let exited = false;
    let floatTween: gsap.core.Tween | null = null;
    let grace = 0;

    const beginWaiting = () => {
      root.classList.add("is-waiting");
      floatTween = gsap.to(notes, {
        y: "-=7",
        duration: 1.8,
        ease: "sine.inOut",
        yoyo: true,
        repeat: -1,
        stagger: 0.14,
      });
    };
    const maybeExit = () => {
      if (exited || !enterDone || !readySeen) return;
      exited = true;
      window.clearTimeout(grace);
      root.classList.remove("is-waiting");
      floatTween?.kill();
      exit.play(0);
    };
    const markSceneReady = () => {
      readySeen = true;
      maybeExit();
    };

    enter.eventCallback("onComplete", () => {
      enterDone = true;
      if (readySeen) maybeExit();
      else beginWaiting();
    });

    // Both doors are always armed: the scene-ready signal, and the grace
    // timer that opens the curtain anyway if the room never reports back.
    const stopWaiting = whenSceneReady(markSceneReady);
    grace = window.setTimeout(markSceneReady, SCENE_GRACE_MS);

    const startTimer = window.setTimeout(() => enter.play(0), 80);

    return () => {
      window.clearTimeout(startTimer);
      window.clearTimeout(grace);
      stopWaiting();
      floatTween?.kill();
      enter.kill();
      exit.kill();
    };
  }, [prefersReducedMotion, visible]);

  if (!visible) return null;
  return (
    <div ref={rootRef} className="site-intro" aria-hidden="true">
      <div className="site-intro__wash">
        <div className="site-intro__staff">
          {Array.from({ length: 5 }, (_, index) => (
            <i key={index} className="site-intro__staff-line" />
          ))}
        </div>
        <div className="site-intro__notes">
          {NOTES.map((note, index) => (
            <span
              key={`${note}-${index}`}
              className="site-intro__note"
              data-note={index}
            >
              {note}
            </span>
          ))}
        </div>
      </div>
      <div className="site-intro__type site-intro__copy">
        <small className="site-intro__eyebrow">01 · Language in motion</small>
        <span className="site-intro__word">
          {WORDMARK.split("").map((letter, index) => (
            <span key={`${letter}-${index}`} className="site-intro__letter">
              <i className="site-intro__letter-glyph">{letter}</i>
            </span>
          ))}
        </span>
        <span className="site-intro__rule" />
        <em className="site-intro__tagline">a moonlit knowledge space</em>
        <span className="site-intro__wait" aria-hidden="true">
          <i />
          <i />
          <i />
        </span>
      </div>
    </div>
  );
}
