function coreBookLink(bookId: string) {
  const categoryByCoreBook: Record<string, KnowledgeCategoryId> = {
    "core-language": "linguistics",
    "core-literature": "literature",
    "core-translation": "translation",
    "core-lexicography": "vocabulary",
    "core-lexicology": "vocabulary",
    "core-writing": "writing",
    "core-culture": "culture",
  };
  const category = categoryByCoreBook[bookId];
  if (!category) return `/book/${bookId}`;
  const book = [
    "knowledge-linguistics",
    "knowledge-literature",
    "knowledge-culture",
    "knowledge-translation",
    "knowledge-writing",
    "knowledge-vocabulary",
  ].find((id) => knowledgeBookById(id)?.categoryId === category);
  return book ? `/book/${book}` : `/library/${category}`;
}

function WordDrawer({
  onClose,
  onOpenGallery,
}: {
  onClose: () => void;
  /** 打开 leafia://wordbook 那扇浏览器窗口：背过的词铺成一片卡片场。 */
  onOpenGallery: () => void;
}) {
  const navigate = useNavigate();
  const initialized = useVocabulary((state) => state.initialized);
  const hydrate = useVocabulary((state) => state.hydrate);
  const words = useVocabulary((state) => state.words);
  const startReviewWithIds = useVocabulary(
    (state) => state.startReviewWithIds,
  );
  const storedPlan = useMemo(loadWordStudyPlan, []);
  const dueCount = words.filter(
    (word) => new Date(word.nextReviewAt).getTime() <= Date.now(),
  ).length;
  const [categoryId, setCategoryId] = useState<string>("all");
  const [dailyLimit, setDailyLimit] = useState(
    storedPlan?.dailyNewLimit ?? 20,
  );
  const [selectedIds, setSelectedIds] = useState<string[]>(
    storedPlan?.wordIds ?? words.slice(0, 20).map((word) => word.id),
  );
  const [notice, setNotice] = useState<string | null>(null);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const visibleWords = words.filter(
    (word) => categoryId === "all" || word.categoryId === categoryId,
  );
  const selected = new Set(selectedIds);
  const mastered = words.filter((word) => word.mastery === "mastered").length;

  const start = () => {
    if (selectedIds.length === 0) {
      setNotice("请先选择至少一个单词。");
      return;
    }
    const plan = createWordStudyPlan(selectedIds, dailyLimit);
    saveWordStudyPlan(plan);
    const queue = buildDailyWordQueue(words, plan);
    startReviewWithIds(queue.length ? queue : selectedIds);
    onClose();
    navigate("/vocabulary");
  };

  return (
    <>
      <div className="leafia-drawer-stats">
        <span>
          <strong>{dueCount}</strong>
          今日到期
        </span>
        <span>
          <strong>{selectedIds.length}</strong>
          已选单词
        </span>
        <span>
          <strong>{mastered}</strong>
          已掌握
        </span>
      </div>

      {/* 抽屉里挑词之后，抬头就能换一种翻法：这扇窗把背过的卡片铺成一片
          会往前漂的场子（浏览器窗口的样子）。 */}
      <button
        type="button"
        className="leafia-drawer-gallery"
        onClick={() => {
          onOpenGallery();
          onClose();
        }}
      >
        <GalleryHorizontalEnd size={15} />
        在卡片场里翻一遍
        <small>leafia://wordbook</small>
      </button>

      <section className="leafia-drawer-section">
        <header>
          <div>
            <span className="knowledge-eyebrow">Daily plan</span>
            <h4>每日新词</h4>
          </div>
          <strong>{dailyLimit}</strong>
        </header>
        <div className="leafia-drawer-segments">
          {[10, 20, 30, 50].map((value) => (
            <button
              type="button"
              key={value}
              className={cn(dailyLimit === value && "is-active")}
              onClick={() => setDailyLimit(value)}
            >
              {value}
            </button>
          ))}
          <label>
            <input
              type="number"
              min={1}
              max={200}
              value={dailyLimit}
              onChange={(event) =>
                setDailyLimit(
                  Math.max(1, Math.min(200, Number(event.target.value) || 1)),
                )
              }
              aria-label="自定义每日新词数"
            />
          </label>
        </div>
        <p className="leafia-drawer-note">
          到期复习词优先。每个单词完成一次词义识别和一次拼写，答错会回到队尾。
        </p>
      </section>

      <section className="leafia-drawer-section">
        <header>
          <div>
            <span className="knowledge-eyebrow">Word source</span>
            <h4>选择背诵范围</h4>
          </div>
          <button
            type="button"
            onClick={() => setSelectedIds(visibleWords.map((word) => word.id))}
          >
            全选
          </button>
        </header>
        <div className="leafia-drawer-segments">
          <button
            type="button"
            className={cn(categoryId === "all" && "is-active")}
            onClick={() => setCategoryId("all")}
          >
            全部
          </button>
          {KNOWLEDGE_CATEGORIES.map((category) => (
            <button
              type="button"
              key={category.id}
              className={cn(categoryId === category.id && "is-active")}
              onClick={() => setCategoryId(category.id)}
            >
              {category.titleZh}
            </button>
          ))}
        </div>
      </section>

      <section className="leafia-word-picker">
        {visibleWords.slice(0, 80).map((word) => {
          const checked = selected.has(word.id);
          return (
            <article
              key={word.id}
              className={cn("leafia-word-flip", checked && "is-selected")}
            >
              <FlipCard
                width={240}
                height={150}
                radius={10}
                background="#fffdf9"
                color="#28302c"
                shadow={false}
                tilt={false}
                ariaLabel={`${word.term} word card`}
                front={
                  <div className="leafia-word-flip__face">
                    <small>{word.partOfSpeech ?? "expression"}</small>
                    <strong>{word.term}</strong>
                    <span>{word.pronunciation ?? "IPA pending"}</span>
                  </div>
                }
                back={
                  <div className="leafia-word-flip__face is-back">
                    <small>Meaning</small>
                    <strong>{word.meaningsZh.join("；")}</strong>
                    <span>{word.definitionEn}</span>
                  </div>
                }
              />
              <button
                type="button"
                className={cn(checked && "is-selected")}
                onClick={() =>
                  setSelectedIds((current) =>
                    current.includes(word.id)
                      ? current.filter((id) => id !== word.id)
                      : [...current, word.id],
                  )
                }
              >
                {checked ? <Check size={13} /> : null}
                {checked ? "已选" : "选入复习"}
              </button>
            </article>
          );
        })}
      </section>

      {notice ? <p className="leafia-drawer-notice">{notice}</p> : null}
      <button
        type="button"
        className="knowledge-primary-button"
        onClick={start}
        disabled={!initialized && words.length === 0}
      >
        <BookOpen size={15} />
        开始两遍复习
      </button>
    </>
  );
}

function KnowledgeDrawer({ onClose }: { onClose: () => void }) {
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const addManualCard = useKnowledge((state) => state.addManualCard);
  const removeCard = useKnowledge((state) => state.removeCard);
  const setCardMastery = useKnowledge((state) => state.setCardMastery);
  const updateCard = useKnowledge((state) => state.updateCard);
  const [query, setQuery] = useState("");
  const [categoryId, setCategoryId] = useState<string>("all");
  const [composerOpen, setComposerOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const [keyPoints, setKeyPoints] = useState("");
  const [terms, setTerms] = useState("");
  const [newCategory, setNewCategory] =
    useState<KnowledgeCategoryId>("linguistics");

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const filtered = cards.filter((card) => {
    if (categoryId !== "all" && card.categoryId !== categoryId) return false;
    const normalized = query.trim().toLowerCase();
    if (!normalized) return true;
    return `${card.title} ${card.summaryZh} ${card.terms.join(" ")}`
      .toLowerCase()
      .includes(normalized);
  });

  const resetComposer = () => {
    setEditingId(null);
    setTitle("");
    setSummary("");
    setKeyPoints("");
    setTerms("");
    setComposerOpen(false);
  };

  const save = () => {
    if (!title.trim() || !summary.trim()) return;
    if (editingId) {
      updateCard(editingId, {
        title: title.trim(),
        summaryZh: summary.trim(),
        keyPoints: keyPoints
          .split(/\n|,/)
          .map((item) => item.trim())
          .filter(Boolean),
        terms: terms
          .split(/\n|,/)
          .map((item) => item.trim())
          .filter(Boolean),
      });
    } else {
      addManualCard({
        categoryId: newCategory,
        title: title.trim(),
        summaryZh: summary.trim(),
        keyPoints: keyPoints
          .split(/\n|,/)
          .map((item) => item.trim())
          .filter(Boolean),
        terms: terms
          .split(/\n|,/)
          .map((item) => item.trim())
          .filter(Boolean),
      });
    }
    resetComposer();
  };

  const edit = (card: KnowledgeCard) => {
    setEditingId(card.id);
    setTitle(card.title);
    setSummary(card.summaryZh);
    setKeyPoints(card.keyPoints.join("\n"));
    setTerms(card.terms.join(", "));
    setComposerOpen(true);
  };

  return (
    <>
      <div className="leafia-drawer-tools">
        <label>
          <Search size={15} />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="搜索知识点或词汇…"
          />
        </label>
        <button
          type="button"
          onClick={() => setComposerOpen((value) => !value)}
        >
          <Plus size={15} />
          新建知识卡
        </button>
      </div>

      <div className="leafia-drawer-segments">
        <button
          type="button"
          className={cn(categoryId === "all" && "is-active")}
          onClick={() => setCategoryId("all")}
        >
          全部
        </button>
        {KNOWLEDGE_CATEGORIES.map((category) => (
          <button
            type="button"
            key={category.id}
            className={cn(categoryId === category.id && "is-active")}
            onClick={() => setCategoryId(category.id)}
          >
            {category.titleZh}
          </button>
        ))}
      </div>

      {composerOpen ? (
        <form
          className="leafia-card-composer"
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <header>
            <strong>{editingId ? "编辑知识卡" : "自建知识卡"}</strong>
            <button type="button" onClick={resetComposer} aria-label="关闭">
              <X size={14} />
            </button>
          </header>
          {!editingId ? (
            <select
              value={newCategory}
              onChange={(event) =>
                setNewCategory(event.target.value as KnowledgeCategoryId)
              }
            >
              {KNOWLEDGE_CATEGORIES.map((category) => (
                <option key={category.id} value={category.id}>
                  {category.titleZh} · {category.title}
                </option>
              ))}
            </select>
          ) : null}
          <input
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            placeholder="知识点标题"
          />
          <textarea
            value={summary}
            onChange={(event) => setSummary(event.target.value)}
            placeholder="核心解释"
            rows={4}
          />
          <textarea
            value={keyPoints}
            onChange={(event) => setKeyPoints(event.target.value)}
            placeholder="关键要点，每行一条"
            rows={3}
          />
          <input
            value={terms}
            onChange={(event) => setTerms(event.target.value)}
            placeholder="关联词汇，用逗号分隔"
          />
          <button
            type="submit"
            className="knowledge-primary-button"
            disabled={!title.trim() || !summary.trim()}
          >
            <BookmarkPlus size={15} />
            {editingId ? "保存修改" : "保存知识卡"}
          </button>
        </form>
      ) : null}

      <section className="leafia-knowledge-cards">
        {filtered.map((card) => {
          const category = KNOWLEDGE_CATEGORIES.find(
            (item) => item.id === card.categoryId,
          );
          const book = card.bookId ? knowledgeBookById(card.bookId) : undefined;
          return (
            <SpotlightCard
              as="article"
              key={card.id}
              className={cn(
                "leafia-knowledge-card",
                card.mastery === "mastered" && "is-mastered",
              )}
              spotlightColor="rgba(47, 135, 171, 0.11)"
            >
              <header>
                <span>
                  {category?.titleZh ?? card.categoryId} ·{" "}
                  {card.source === "manual" ? "自建" : "书本收藏"}
                </span>
                <button
                  type="button"
                  aria-label={`删除 ${card.title}`}
                  onClick={() => removeCard(card.id)}
                >
                  <Trash2 size={13} />
                </button>
              </header>
              <h4>{card.title}</h4>
              <p>{card.summaryZh}</p>
              {book ? <small>{book.title}</small> : null}
              {card.sourceQuote ? <blockquote>{card.sourceQuote}</blockquote> : null}
              <footer>
                <button type="button" onClick={() => edit(card)}>
                  编辑
                </button>
                <button
                  type="button"
                  onClick={() =>
                    setCardMastery(
                      card.id,
                      card.mastery === "mastered" ? "learning" : "mastered",
                    )
                  }
                >
                  {card.mastery === "mastered" ? (
                    <>
                      <CheckCircle2 size={13} />
                      已掌握
                    </>
                  ) : (
                    "标记掌握"
                  )}
                </button>
              </footer>
            </SpotlightCard>
          );
        })}
        {filtered.length === 0 ? (
          <div className="leafia-drawer-empty">
            <FileText size={20} />
            <strong>还没有知识卡</strong>
            <p>在书本中收藏知识点，或在这里新建一张。</p>
          </div>
        ) : null}
      </section>
    </>
  );
}

function RecentDrawer({
  events,
  books,
  notes,
  onRemoveNote,
  onClose,
}: {
  events: StudyEvent[];
  books: ReaderBook[];
  notes: DrawerNote[];
  onRemoveNote: (noteId: string) => void;
  onClose: () => void;
}) {
  const navigate = useNavigate();
  const [kind, setKind] = useState<StudyEvent["kind"] | "all">("all");
  const filtered = [...events]
    .filter((event) => kind === "all" || event.kind === kind)
    .sort((left, right) => right.at - left.at);
  const sortedNotes = drawerNotesIn(notes, "notes").reverse();
  const bookFor = (bookId: string) =>
    books.find((book) => String(book.id).split("#")[0] === bookId);

  const openEvent = (event: StudyEvent) => {
    onClose();
    if (event.kind === "practice" || event.kind === "word-review") {
      navigate("/practice");
      return;
    }
    if (event.kind === "card-created") {
      navigate("/shelf?drawer=materials");
      return;
    }
    if ("bookId" in event) navigate(coreBookLink(event.bookId));
  };

  return (
    <>
      <div className="leafia-drawer-segments">
        {(
          [
            ["all", "全部"],
            ["open", "打开书本"],
            ["topic", "学习模块"],
            ["practice", "复习练习"],
            ["complete", "完成"],
            ["resume", "恢复学习"],
          ] as const
        ).map(([value, label]) => (
          <button
            type="button"
            key={value}
            className={cn(kind === value && "is-active")}
            onClick={() => setKind(value)}
          >
            {label}
          </button>
        ))}
      </div>

      {/* 便条留在这一页上：以前它们摆在面板顶头那只文件夹里，
          现在按网页的样子排成一份清单，删除就在行尾。 */}
      {sortedNotes.length ? (
        <section className="leafia-drawer-notes">
          <header>
            <span className="knowledge-eyebrow">Notes</span>
            <h4>便条 · 记录今天</h4>
          </header>
          <ul>
            {sortedNotes.map((note) => (
              <li key={note.id}>
                <span>
                  <strong>{note.title}</strong>
                  <small>{note.meta || "本机便条"}</small>
                </span>
                <button
                  type="button"
                  aria-label={`删除 ${note.title}`}
                  onClick={() => onRemoveNote(note.id)}
                >
                  <Trash2 size={13} />
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <section className="leafia-timeline">
        {filtered.slice(0, 120).map((event) => {
          const eventBookId = "bookId" in event ? event.bookId : null;
          const book = eventBookId ? bookFor(eventBookId) : null;
          const title =
            event.kind === "practice"
              ? `练习分区 ${event.region + 1}`
              : event.kind === "word-review"
                ? "词汇复习"
                : event.kind === "card-created"
                  ? "新建知识卡"
                  : book?.zhTitle || eventBookId || "学习记录";
          const detail =
            event.kind === "topic"
              ? `学习模块 · ${event.topic}`
              : event.kind === "practice"
                ? `${event.keys} 个琴键 · ${formatRelativeTime(event.at)}`
                : event.kind === "complete"
                  ? `已标记完成 · ${formatRelativeTime(event.at)}`
                  : event.kind === "resume"
                    ? `恢复学习 · ${formatRelativeTime(event.at)}`
                    : event.kind === "knowledge-review"
                      ? `${event.correct ? "知识点答对" : "知识点需复习"} · ${formatRelativeTime(event.at)}`
                      : event.kind === "quiz-completed"
                        ? `${event.correct}/${event.total} 正确 · ${formatRelativeTime(event.at)}`
                        : event.kind === "word-review"
                          ? `${event.passed}/${event.reviewed} 通过 · ${formatRelativeTime(event.at)}`
                          : event.kind === "card-created"
                            ? `知识卡已保存 · ${formatRelativeTime(event.at)}`
                            : `打开书本 · ${formatRelativeTime(event.at)}`;
          return (
            <button
              type="button"
              key={`${event.kind}-${event.at}-${"bookId" in event ? event.bookId : "review"}`}
              className="leafia-timeline__item"
              onClick={() => openEvent(event)}
            >
              <span className={cn("leafia-timeline__marker", `is-${event.kind}`)}>
                {event.kind === "practice" ? (
                  <Sparkles size={13} />
                ) : (
                  <Clock3 size={13} />
                )}
              </span>
              <span>
                <strong>{title}</strong>
                <small>{detail}</small>
              </span>
              <ArrowUpRight size={14} />
            </button>
          );
        })}
        {filtered.length === 0 ? (
          <div className="leafia-drawer-empty">
            <Clock3 size={20} />
            <strong>还没有学习记录</strong>
            <p>打开书本、学习模块或完成一次复习后，这里会记录真实事件。</p>
          </div>
        ) : null}
      </section>
    </>
  );
}


export function LeafiaDrawerPanel({
  drawerId,
  studyLog,
  books,
  drawerNotes,
  onRemoveNote,
  onOpenWords,
  onClose,
}: {
  drawerId: DrawerId;
  studyLog: StudyEvent[];
  books: ReaderBook[];
  drawerNotes: DrawerNote[];
  onRemoveNote: (noteId: string) => void;
  /** 词汇积累抽屉 → 卡片场那扇浏览器窗口。 */
  onOpenWords: () => void;
  onClose: () => void;
}) {
  const reducedMotion = useReducedMotion();
  const copy = DRAWER_COPY[drawerId];

  return (
    <AnimatePresence>
      <>
        <motion.aside
          className="study-shelf__drawer-panel leafia-functional-drawer"
          aria-label={`${copy.zhLabel}抽屉`}
          initial={{ opacity: 0, y: 72, scale: 0.96 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 48, scale: 0.98 }}
          transition={{
            duration: reducedMotion ? 0.01 : 0.4,
            ease: [0.22, 1, 0.36, 1],
          }}
        >
          {/* 抽屉拉开之后不是一张卡片，而是一页「网页」：标签页、地址栏、
              左上角第一颗圆点就是关闭 —— 和单词本、练习册那两扇窗同一副样子。 */}
          <BrowserFrame
            label={copy.zhLabel}
            url={copy.url}
            onClose={onClose}
          >
            <div className="leafia-functional-drawer__body">
              <header className="leafia-functional-drawer__head">
                <span>
                  <small>{copy.label}</small>
                  <strong>{copy.zhLabel}</strong>
                  <em>{copy.description}</em>
                </span>
                <button type="button" onClick={onClose} aria-label="关闭">
                  <X size={15} />
                </button>
              </header>
              {drawerId === "collection" ? (
                <WordDrawer onClose={onClose} onOpenGallery={onOpenWords} />
              ) : drawerId === "materials" ? (
                <KnowledgeDrawer onClose={onClose} />
              ) : (
                <RecentDrawer
                  events={studyLog}
                  books={books}
                  notes={drawerNotes}
                  onRemoveNote={onRemoveNote}
                  onClose={onClose}
                />
              )}
            </div>
          </BrowserFrame>
        </motion.aside>
      </>
    </AnimatePresence>
  );
}
