import { Lock, RotateCw, X } from "lucide-react";
import type { ReactNode } from "react";
import "./browser-frame.css";

/**
 * 一扇「浏览器窗口」。
 *
 * 词汇积累、练习空间这类内容不再是书房里的一张卡片，而是打开的网页：
 * 顶上一条标签页写着页面名，下面是地址栏（leafia:// 开头，跟真网址一样
 * 配一把小锁），再往下才是内容。关闭按钮做成窗口左上角的第一颗圆点，
 * 和真的窗口一样在它该在的位置 —— 面板的 ✕ 反而可以省掉。
 */
export function BrowserFrame({
  label,
  url,
  children,
  onClose,
  actions,
  className = "",
}: {
  /** 标签页上的页面名。 */
  label: string;
  /** 地址栏里的地址，例如 leafia://words。 */
  url: string;
  children: ReactNode;
  onClose?: () => void;
  /** 地址栏右侧的额外按钮。 */
  actions?: ReactNode;
  className?: string;
}) {
  return (
    <div className={`browser-frame ${className}`.trim()} role="dialog" aria-label={label}>
      <header className="browser-frame__chrome">
        <div className="browser-frame__dots">
          <button
            type="button"
            className="browser-frame__dot browser-frame__dot--close"
            onClick={onClose}
            aria-label={`关闭 ${label}`}
          >
            <X size={9} aria-hidden="true" />
          </button>
          <span className="browser-frame__dot browser-frame__dot--min" aria-hidden="true" />
          <span className="browser-frame__dot browser-frame__dot--max" aria-hidden="true" />
        </div>
        <div className="browser-frame__tab">
          <span className="browser-frame__favicon" aria-hidden="true">
            {label.slice(0, 1).toUpperCase()}
          </span>
          <span className="browser-frame__tab-label">{label}</span>
        </div>
        <div className="browser-frame__bar">
          <Lock size={11} aria-hidden="true" />
          <span className="browser-frame__url">{url}</span>
          <RotateCw size={12} aria-hidden="true" className="browser-frame__reload" />
          {actions ? <span className="browser-frame__actions">{actions}</span> : null}
        </div>
      </header>
      <div className="browser-frame__page">{children}</div>
    </div>
  );
}

export default BrowserFrame;
