/**
 * 账号与抽屉便条的 HTTP 客户端。
 *
 * 这里保留状态码：401 表示「这台浏览器没登录」，抽屉就退回本机模式；
 * 409 表示「这个抽屉满了」。都当正常业务结果处理，不往控制台扔错误。
 */
import type {
  AuthUser,
  DrawerNote,
  ShelfDrawerId,
  ThemeId,
} from "@inkflow/shared";

const API_BASE = import.meta.env.VITE_API_URL || "";

export class ApiError extends Error {
  readonly status: number;
  readonly code?: string;

  constructor(message: string, status: number, code?: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.code = code;
  }
}

interface ErrorPayload {
  error?: string;
  message?: string;
}

async function requestJson<T>(
  path: string,
  init: RequestInit & { token?: string } = {},
): Promise<T> {
  const { token, ...rest } = init;
  const response = await fetch(`${API_BASE}${path}`, {
    ...rest,
    headers: {
      // 没有请求体时不能带 Content-Type: application/json —— Fastify 会当成
      // 「空了却声明是 JSON」直接 400（开发者登录没有 body，就栽在这一点上）。
      ...(rest.body ? { "Content-Type": "application/json" } : {}),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...rest.headers,
    },
  });

  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as
      | ErrorPayload
      | null;
    throw new ApiError(
      payload?.message ?? payload?.error ?? `Request failed: ${response.status}`,
      response.status,
      payload?.error,
    );
  }

  return (await response.json()) as T;
}

export interface AuthSessionPayload {
  user: AuthUser;
  accessToken: string;
  refreshToken: string;
  expiresAt: string;
}

export function loginDeveloper() {
  return requestJson<AuthSessionPayload>("/v1/auth/dev", { method: "POST" });
}

export function registerWithPassword(input: {
  displayName: string;
  email: string;
  password: string;
}) {
  return requestJson<AuthSessionPayload>("/v1/auth/register", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

export function loginWithPassword(input: {
  email: string;
  password: string;
}) {
  return requestJson<AuthSessionPayload>("/v1/auth/password", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

export function requestSmsCode(phone: string) {
  return requestJson<{ ok: boolean; expiresIn: number; devCode?: string }>(
    "/v1/auth/sms/request",
    { method: "POST", body: JSON.stringify({ phone }) },
  );
}

export function verifySmsCode(phone: string, code: string) {
  return requestJson<AuthSessionPayload>("/v1/auth/sms/verify", {
    method: "POST",
    body: JSON.stringify({ phone, code }),
  });
}

export function requestPhoneBindCode(token: string, phone: string) {
  return requestJson<{ ok: boolean; expiresIn: number; devCode?: string }>(
    "/v1/auth/phone/bind/request",
    {
      method: "POST",
      token,
      body: JSON.stringify({ phone }),
    },
  );
}

export function verifyPhoneBindCode(
  token: string,
  phone: string,
  code: string,
) {
  return requestJson<{ user: AuthUser }>("/v1/auth/phone/bind/verify", {
    method: "POST",
    token,
    body: JSON.stringify({ phone, code }),
  });
}

export function fetchAccount(token: string) {
  return requestJson<{ user: AuthUser }>("/v1/auth/me", { token });
}

export function updateRemoteTheme(token: string, themeId: ThemeId) {
  return requestJson<{ user: AuthUser }>("/v1/auth/me/preferences", {
    method: "PATCH",
    token,
    body: JSON.stringify({ themeId }),
  });
}

export function signOutRemote(token: string) {
  return requestJson<{ ok: boolean }>("/v1/auth/logout", {
    method: "POST",
    token,
  });
}

export function listRemoteDrawerNotes(token: string) {
  return requestJson<{ notes: DrawerNote[]; limit: number }>(
    "/v1/drawer-notes",
    { token },
  );
}

export function createRemoteDrawerNote(token: string, note: DrawerNote) {
  return requestJson<{ note: DrawerNote | null; duplicated?: boolean }>(
    "/v1/drawer-notes",
    {
      method: "POST",
      token,
      body: JSON.stringify({
        id: note.id,
        drawerId: note.drawerId as ShelfDrawerId,
        title: note.title,
        meta: note.meta,
      }),
    },
  );
}

export function deleteRemoteDrawerNote(token: string, noteId: string) {
  return requestJson<{ ok: boolean }>(
    `/v1/drawer-notes/${encodeURIComponent(noteId)}`,
    { method: "DELETE", token },
  );
}
