function StaticShelfFallback({
  rows,
  onOpen,
  onReady,
}: {
  rows: ShelfRow[];
  onOpen: (book: ReaderBook) => void;
  onReady: () => void;
}) {
  useEffect(() => {
    onReady();
  }, [onReady]);

  return (
    <div className="study-shelf__fallback" aria-label="Leafia 书架">
      <div className="study-shelf__fallback-case">
        <div className="study-shelf__fallback-rows">
          {rows.map((row) => (
            <section key={row.number} className="study-shelf__fallback-row">
              <header>
                <span>{row.number}</span>
                <small>{row.english}</small>
              </header>
              <div className="study-shelf__fallback-books">
                {row.books.map((book) => (
                  <button
                    key={book.id}
                    type="button"
                    style={{
                      background: BOOK_COLORS[book.id] ?? FILLER_PALETTE[0],
                    }}
                    onClick={() => onOpen(book)}
                  >
                    <span>{book.title}</span>
                  </button>
                ))}
              </div>
            </section>
          ))}
        </div>
        <div className="study-shelf__fallback-keys" aria-hidden="true">
          {Array.from({ length: 14 }, (_, index) => (
            <i key={index} />
          ))}
        </div>
      </div>
    </div>
  );
}

