/**
 * 贴纸可以拖着挪位置，但只在柜子左侧这块面板里挪：范围取左立柱的内侧
 * （面板 x 从 -2.62 到开口 -1.66），每张贴纸再按自己的半径收一圈，
 * 挪到边上也不会压出柜体。挪过的位置记在本机，下次打开还在。
 */
const STICKER_FIELD = { minX: -2.46, maxX: -1.78, minY: -2.02, maxY: 2.08 };
const STICKER_POSITIONS_KEY = "inkflow:sticker-positions:v1";

function loadStickerPositions(): Record<string, { x: number; y: number }> {
  if (typeof localStorage === "undefined") return {};
  try {
    const raw = localStorage.getItem(STICKER_POSITIONS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: Record<string, { x: number; y: number }> = {};
    for (const [id, value] of Object.entries(parsed)) {
      if (!value || typeof value !== "object") continue;
      const { x, y } = value as { x?: unknown; y?: unknown };
      if (typeof x === "number" && typeof y === "number") out[id] = { x, y };
    }
    return out;
  } catch {
    return {};
  }
}

function saveStickerPositions(
  positions: Record<string, { x: number; y: number }>,
) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(STICKER_POSITIONS_KEY, JSON.stringify(positions));
  } catch {
    // 存不下就只留这一次的位置。
  }
}

