/** Local-timezone day key — matches the local-time style of the app's date helpers. */
function dayKey(date: Date = new Date()): string {
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
  ].join("-");
}

/** FNV-1a — a stable string hash, so the same day always picks the same quote. */
function hashString(value: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function pickDailyQuote(
  quotes: QuoteItem[],
  date: Date = new Date(),
): QuoteItem {
  const pool = quotes.filter((quote) => quote.text.trim().length > 0);
  if (pool.length === 0) return SYSTEM_QUOTES[0]!;
  return pool[hashString(dayKey(date)) % pool.length] ?? pool[0]!;
}

function normalizeQuote(value: unknown): QuoteItem | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<QuoteItem>;
  if (typeof candidate.text !== "string" || !candidate.text.trim()) return null;
  return {
    id: typeof candidate.id === "string" ? candidate.id : `user-${hashString(candidate.text)}`,
    text: candidate.text.trim().slice(0, 240),
    author:
      typeof candidate.author === "string" && candidate.author.trim()
        ? candidate.author.trim().slice(0, 48)
        : "我",
    kind: "user",
  };
}

function loadQuotes(): QuoteItem[] {
  if (typeof localStorage === "undefined") return [...SYSTEM_QUOTES];
  try {
    const parsed = JSON.parse(
      localStorage.getItem(QUOTE_STORAGE_KEY) ?? "null",
    );
    if (!Array.isArray(parsed)) return [...SYSTEM_QUOTES];
    const storedUsers = parsed
      .map(normalizeQuote)
      .filter((quote): quote is QuoteItem => quote !== null)
      .filter((quote) => !quote.id.startsWith("system-"));
    return [...SYSTEM_QUOTES, ...storedUsers];
  } catch {
    return [...SYSTEM_QUOTES];
  }
}

function saveUserQuotes(quotes: QuoteItem[]) {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(
    QUOTE_STORAGE_KEY,
    JSON.stringify(quotes.filter((quote) => quote.kind === "user")),
  );
}

