import {
  ArrowLeft,
  ArrowUpRight,
  Brain,
  BookmarkPlus,
  Check,
  Compass,
  Globe2,
  Languages,
  Sparkles,
} from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";
import { cn } from "../../lib/cn";
import { IpaGallery } from "./IpaGallery";
import {
  LANGUAGE_MAP_NODES,
  type LanguageMapNode,
  type LanguageMapNodeId,
} from "./languageLabData";
import { PhoneticsStudio } from "./PhoneticsStudio";
import { PhonologyDetective } from "./PhonologyDetective";
import type { CollectedWord } from "./WordsExplorer";
import "./language-lab.css";

type LanguageView =
  | "map"
  | "sound"
  | "phonetics"
  | "ipa"
  | "detective";

const DISCOVERY_STORAGE_KEY = "inkflow:language-lab-discoveries:v1";

function loadDiscoveries(): string[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const parsed = JSON.parse(
      localStorage.getItem(DISCOVERY_STORAGE_KEY) ?? "[]",
    );
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function LanguageLab({
  savedIds,
  completed,
  onStudyTopic,
  onToggleComplete,
  onSave,
  onClose,
}: {
  savedIds: string[];
  completed: boolean;
  /** 点开一条知识路径 = 记一次「最近章节」，书架第一层据此显示进度。 */
  onStudyTopic: (topic: string) => void;
  onToggleComplete: (done: boolean) => void;
  onSave: (item: CollectedWord) => void;
  onClose: () => void;
}) {
  const [view, setView] = useState<LanguageView>("map");
  const [selectedNode, setSelectedNode] =
    useState<LanguageMapNode | null>(null);
  const [discoveries, setDiscoveries] = useState<string[]>(loadDiscoveries);

  const unlockDiscovery = (id: string, title: string) => {
    setDiscoveries((current) => {
      const next = current.includes(id) ? current : [...current, id];
      if (typeof localStorage !== "undefined") {
        localStorage.setItem(DISCOVERY_STORAGE_KEY, JSON.stringify(next));
      }
      return next;
    });
    onSave({
      id,
      title,
      meta: "Language Lab · Discovery unlocked",
      kind: "save",
    });
  };

  const goBack = () => {
    if (view === "map") {
      onClose();
      return;
    }
    setView("map");
  };

  return (
    <motion.section
      className="language-lab"
      aria-label="Language Lab"
      initial={{ opacity: 0, y: 24, scale: 0.978 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: 18, scale: 0.986 }}
      transition={{ duration: 0.42, ease: [0.22, 1, 0.36, 1] }}
    >
      <header className="language-lab__header">
        <button type="button" onClick={goBack}>
          <ArrowLeft size={16} />
          {view === "map" ? "返回书架" : "返回 Language Map"}
        </button>
        <span>
          <small>Language Lab · Explore</small>
          <strong>语言学探索空间</strong>
        </span>
        <div className="language-lab__discoveries">
          <Sparkles size={13} />
          <span>{discoveries.length} discoveries</span>
        </div>
        {/* 样式和书架上其它「标记为已完成」是同一套（全局 CSS）。 */}
        <button
          type="button"
          className={cn("study-shelf__complete", completed && "is-done")}
          onClick={() => onToggleComplete(!completed)}
        >
          <Check size={14} />
          {completed ? "已完成" : "标记为已完成"}
        </button>
      </header>

      <AnimatePresence mode="wait">
        {view === "map" ? (
          <motion.div
            key="map"
            className="language-lab__view"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
          >
            <LanguageMap
              selectedNode={selectedNode}
              savedIds={savedIds}
              onSelect={(node) => {
                setSelectedNode(node);
                if (node) onStudyTopic(node.label);
              }}
              onOpenSoundLab={() => setView("sound")}
              onSave={onSave}
            />
          </motion.div>
        ) : view === "sound" ? (
          <SoundLabHub
            key="sound"
            savedIds={savedIds}
            discoveries={discoveries}
            onOpen={setView}
            onSave={onSave}
          />
        ) : view === "phonetics" ? (
          <PhoneticsStudio
            key="phonetics"
            savedIds={savedIds}
            onBack={() => setView("sound")}
            onSave={onSave}
            onDiscovery={unlockDiscovery}
          />
        ) : view === "ipa" ? (
          <IpaGallery
            key="ipa"
            savedIds={savedIds}
            onBack={() => setView("sound")}
            onSave={onSave}
          />
        ) : (
          <PhonologyDetective
            key="detective"
            savedIds={savedIds}
            onBack={() => setView("sound")}
            onSave={onSave}
            onDiscovery={unlockDiscovery}
          />
        )}
      </AnimatePresence>
    </motion.section>
  );
}

function LanguageMap({
  selectedNode,
  savedIds,
  onSelect,
  onOpenSoundLab,
  onSave,
}: {
  selectedNode: LanguageMapNode | null;
  savedIds: string[];
  onSelect: (node: LanguageMapNode | null) => void;
  onOpenSoundLab: () => void;
  onSave: (item: CollectedWord) => void;
}) {
  const saveId = selectedNode
    ? `language-concept-${selectedNode.id}`
    : "";
  const saved = savedIds.includes(saveId);

  return (
    <div className="language-map">
      <div className="language-map__canvas">
        <svg viewBox="0 0 760 540" aria-hidden="true">
          <path d="M380 270 C292 202 228 154 154 105" />
          <path d="M380 270 C300 304 226 332 136 372" />
          <path d="M380 270 C380 190 380 112 380 52" />
          <path d="M380 270 C462 202 528 154 606 102" />
          <path d="M380 270 C476 308 548 347 625 430" />
        </svg>
        <div className="language-map__core">
          <Languages size={22} />
          <small>Core field</small>
          <strong>LANGUAGE</strong>
          <span>选择一条知识路径开始探索</span>
        </div>
        {LANGUAGE_MAP_NODES.map((node, index) => (
          <button
            type="button"
            key={node.id}
            className={cn(
              "language-map__node",
              `language-map__node--${index + 1}`,
              selectedNode?.id === node.id && "is-active",
            )}
            onClick={() => {
              onSelect(node);
              if (node.id === "sound") onOpenSoundLab();
            }}
          >
            <small>{node.branches.length} branches</small>
            <strong>{node.label}</strong>
            <span>{node.branches.join(" · ")}</span>
          </button>
        ))}
      </div>

      <aside className="language-map__detail">
        {selectedNode ? (
          <motion.div
            key={selectedNode.id}
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <span className="eyebrow">Language concept</span>
            <h2>{selectedNode.label}</h2>
            <div className="language-map__branches">
              {selectedNode.branches.map((branch) => (
                <span key={branch}>{branch}</span>
              ))}
            </div>
            <p>{selectedNode.summary}</p>
            <section>
              <small>Explore task</small>
              <strong>{selectedNode.task}</strong>
            </section>
            <button
              type="button"
              className={cn("language-lab__save", saved && "is-saved")}
              disabled={saved}
              onClick={() =>
                onSave({
                  id: saveId,
                  title: `${selectedNode.label} · ${selectedNode.concept}`,
                  meta: "Language Lab · Linguistic concept",
                  kind: "save",
                })
              }
            >
              {saved ? <Check size={14} /> : <BookmarkPlus size={14} />}
              {saved ? "已保存" : "Save"}
            </button>
          </motion.div>
        ) : (
          <div className="language-map__prompt">
            <Compass size={22} />
            <strong>Choose a path</strong>
            <p>点击地图节点，观察概念、案例和探索任务。</p>
          </div>
        )}
      </aside>
    </div>
  );
}

function SoundLabHub({
  savedIds,
  discoveries,
  onOpen,
  onSave,
}: {
  savedIds: string[];
  discoveries: string[];
  onOpen: (view: LanguageView) => void;
  onSave: (item: CollectedWord) => void;
}) {
  const labs = [
    {
      id: "phonetics",
      kicker: "Mouth · Air · Voice",
      title: "Phonetics Studio",
      description: "点击发音器官，观察声音如何被制造。",
      icon: Sparkles,
      discovery: "Anatomy observed",
    },
    {
      id: "ipa",
      kicker: "Symbols · Cards",
      title: "IPA Gallery",
      description: "收集音标卡片，理解 Manner、Place 与 Example。",
      icon: BookmarkPlus,
      discovery: "IPA collector",
    },
    {
      id: "detective",
      kicker: "Observe · Infer · Unlock",
      title: "Phonology Detective",
      description: "追踪 /l/ 的不同形式，解锁 Phone、Phoneme、Allophone。",
      icon: Brain,
      discovery: "Phoneme discovered",
    },
  ] as const;

  return (
    <motion.div
      className="sound-lab-hub"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
    >
      <header>
        <div>
          <span className="eyebrow">Sound · Word · Pattern</span>
          <h2>SOUND LAB</h2>
          <p>声音不是孤立的符号，而是由身体、规则和语境共同构成的系统。</p>
        </div>
        <span className="sound-lab-hub__count">
          {discoveries.filter((item) => item.startsWith("language-")).length}
          /3 unlocked
        </span>
      </header>
      <div className="sound-lab-hub__grid">
        {labs.map((lab, index) => {
          const Icon = lab.icon;
          const unlocked = discoveries.some((item) =>
            lab.id === "detective"
              ? item === "language-discovery-allophone"
              : lab.id === "ipa"
                ? item === "language-ipa-p"
                : item === "language-organ-pharyngeal",
          );
          return (
            <motion.button
              type="button"
              key={lab.id}
              initial={{ opacity: 0, y: 18 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.07 }}
              onClick={() => onOpen(lab.id as LanguageView)}
            >
              <span>
                <Icon size={18} />
              </span>
              <small>{lab.kicker}</small>
              <strong>{lab.title}</strong>
              <p>{lab.description}</p>
              <em>
                {unlocked ? <Check size={12} /> : <ArrowUpRight size={12} />}
                {unlocked ? lab.discovery : "Explore"}
              </em>
            </motion.button>
          );
        })}
      </div>
      <div className="sound-lab-hub__footer">
        <span>
          <Globe2 size={13} />
          Phonetics → Phonology → Meaning
        </span>
        <span>{savedIds.length} items in Collection</span>
      </div>
    </motion.div>
  );
}
